std::mutex m;
State state = State::idle;                    // guarded by m

bool try_start() {
    std::unique_lock<std::mutex> lk(m, std::try_to_lock);
    if (!lk.owns_lock() || state != State::idle) return false;  // balk
    state = State::running;                   // guard + transition, one lock
    return true;                              // released by ~unique_lock
}
